#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, M, C;
    if (scanf("%d %d %d", &N, &M, &C) != 3) return 0;

    /* best[s] = musica amada pelo amigo mais antigo que detesta s (0 se ninguem detesta s) */
    int *best = (int *)calloc((size_t)(M + 1), sizeof(int));
    unsigned char *visited = (unsigned char *)calloc((size_t)(M + 1), sizeof(unsigned char));
    if (!best || !visited) return 0;

    for (int i = 0; i < N; i++) {
        int A, D;
        scanf("%d %d", &A, &D);
        /* a primeira ocorrencia (menor indice = cliente mais antigo) define quem troca */
        if (best[D] == 0) best[D] = A;
    }

    long long count = 0;
    int cur = C;
    int infinite = 0;

    while (best[cur] != 0) {
        if (visited[cur]) { /* estado ja visitado -> ciclo, trocas interminaveis */
            infinite = 1;
            break;
        }
        visited[cur] = 1;
        cur = best[cur];
        count++;
    }

    if (infinite) printf("-1\n");
    else printf("%lld\n", count);

    free(best);
    free(visited);
    return 0;
}
